como fazer a bola completar um círculo completo pra sair do buraco?

void moveBallInSpiral(Vector3 ballPosition, Vector3 pocketPosition,
      double speed, double angularSpeed, double thresholdStraight) {
    // Calcula o vetor direção do centro do buraco para a bola
    Vector3 direction = ballPosition - pocketPosition;

    // Calcula o raio atual (distância entre a bola e o buraco)
    double radius = direction.length;

    // Decide entre movimento reto ou espiral
    bool moveStraight =
        radius <= thresholdStraight; // Distância próxima ao buraco

    if (moveStraight) {
      // MOVIMENTO DIRETO/DIAGONAL
      // Move diretamente para o buraco reduzindo a posição gradualmente
      double stepX = (pocketPosition.x - ballPosition.x) * (speed / radius);
      double stepY = (pocketPosition.y - ballPosition.y) * (speed / radius);

      // Atualiza a posição da bola
      double newX = ballPosition.x + stepX;
      double newY = ballPosition.y + stepY;

      balls[0].position.setValues(newX, newY, ballPosition.z);

      // Verifica se chegou ao buraco
      if (radius <= speed) {
        ballPosition.setFrom(pocketPosition); // Posiciona no centro
      }
    } else {
      // MOVIMENTO EM ESPIRAL
      // Determina o sentido do giro baseado no vetor direção
      double crossProductZ =
          direction.x * -1 * direction.y; // Simula Z do produto vetorial

      // Ajusta o sinal da velocidade angular com base no produto vetorial
      if (crossProductZ > 0) {
        angularSpeed = angularSpeed.abs(); // Sentido horário
      } else {
        angularSpeed = -angularSpeed.abs(); // Sentido anti-horário
      }

      // Reduz o raio gradualmente para mover a bola para o centro
      radius = max(0, radius - speed);

      // Atualiza o ângulo da rotação
      double theta = atan2(direction.y, direction.x); // Ângulo atual
      theta += angularSpeed; // Incrementa o ângulo para girar

      // Calcula a nova posição da bola usando a equação paramétrica do círculo
      double newX = pocketPosition.x + radius * cos(theta);
      double newY = pocketPosition.y + radius * sin(theta);

      // Define a nova posição da bola
      balls[0].position.setValues(newX, newY, ballPosition.z);

      // Verifica se a bola chegou ao centro
      if (radius <= speed) {
        ballPosition.setFrom(pocketPosition); // Posiciona no centro
      }
    }
  }

