using UnityEngine;

public class PinBallSpiral : MonoBehaviour
{
    [Header("Partes do Jogo")]
    public Transform[] balls;          //[0] = ball, o restante pode ser usado para múltiplas bolas
    public Transform pocket;
    public float controls // [TMB] velocidade linear (m/s)
    public float angularSpin // rad/s (inclinação da espiraisidade)
    public float smoothstep; // distância que ainda vai girar antes de passar ao passo reto

    private GameObject ball; // salvo para conveniência

    void Start()
    {
        ball = balls[0].gameObject;
    }

    void Update()
    {
        Vector3 ballVec = ball.transform.position;
        Vector3 pocketVec = pocket.position;
        Vector3 direction = ballVec - pocketVec;
        double radius = direction.magnitude;
        double threshold = smoothstep; // use float -> double

        // 1️⃣  Distância muito baixa → caminho reto
        bool needStraight = radius <= threshold;

        if (needStraight)
        {
            // Passo reto ( o passo tem unidades de distância direta )
            float smoothStepDelta = direction.magnitude < 1f ? 0.5f : 1f; // pequeno ajuste para evitar divisão zero
            Vector3 step = direction.normalized * controls * Time.deltaTime * smoothStepDelta;
            ball.transform.position += step;
        }
        else
        {
            // 2️⃣  Cuspidela de “cima para baixo”
            float spinSpeed = angularSpin * Time.deltaTime; // rad → "deg ou m"

            // 2a️⃣  Determine sentido (horário/anti‑horário) – assumimos rotação ao redor do eixo Y
            //    Se quiser rotacionar ao redor de outro eixo, ajuste spinAxis.
            Quaternion targetSpin = Quaternion.Euler(0f, 1f, 0f);
            //    Ponto de toque + direção = ângulo
            float baseAngle = Mathf.Asin((ballVec.y - pocketVec.y) / radius);
            float baseU = Mathf.Cos(baseAngle) * (ballVec.x - pocketVec.x) / radius;
            float baseV = Mathf.Cos(baseAngle) * (ballVec.y - pocketVec.y) / radius;

            //    Pinheiro (baixo ponto de retiro) → cálculo de spin
            bool clockwise = Mathf.Sin(baseAngle + spinSpeed) > 0; // positivo -> sentido anti‑horário (do ponto de vista do jogador)

            if (clockwise)
                spinSpeed *= -1;

            // 2b️⃣  Move a raio gradualmente
            radius = Mathf.Max(0f, radius - controls);
            float theta = Mathf.Asin((ballVec.y - pocketVec.y) / radius) + (clockwise ? 0.0f : spinSpeed);

            //.position no círculo
            ball.transform.position = pocketVec + new Vector3(Mathf.Cos(theta) * radius, Mathf.Sin(theta) * radius, ballVec.z);
        }

        // 3️⃣  Acabamento – quando o raio ficou pequeno (≤0,5 passo) entrem agulha no centro do buraco
        //    (\u02c6ball.\u02c6ball.\u02c6ball. position = pocket...) // mantenha z
        if (radius <= controls * 0.5f) // 0,5 passo serve de critério flexível
        {
            ball.transform.position = new Vector3(pocketVec.x, pocketVec.y, ball.transform.position.z);
        }
    }
}
```

